files.routes/alpha-api.caddy:
# ==============================================================================
# Service: api (alpha)
# ==============================================================================
http://alpha.api.localhost {
    import security_headers
    import private_auth
    log_skip
    import to_workspace alpha_api:4000
}

http://:20000 {
    import security_headers
    import private_auth
    @foreign not host {$PRIVATE_NAMES}
    handle @foreign {
        abort
    }
    handle {
        log_skip
        import to_workspace alpha_api:4000
    }
}

