# ==============================================================================
http://alpha.good.localhost {
    import security_headers
    import private_auth
    route {
    header X-A b
    handle /h {
     respond "hi" 200
    }
        import to_workspace alpha_good:7000
    }
}

http://:20003 {
    import security_headers
    import private_auth
    @foreign not host {$PRIVATE_NAMES}
    handle @foreign {
        abort
    }
    handle {
        route {
        header X-A b
        handle /h {
         respond "hi" 200
        }
            import to_workspace alpha_good:7000
        }
    }
}

