    import security_headers
    @foreign not host {$PUBLIC_NAMES}
    handle @foreign {
        abort
    }
    handle {
        route {
        header X-A b
        handle /h {
         respond "hi" 200
        }
            import to_workspace alpha_good:7000
        }
    }
}

